using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // EF Core 9 renamed the default discriminator from "Discriminator" to "$type".
            // Preserve the old name so existing 500K documents and direct SQL queries
            // (e.g. WHERE c.Discriminator = 'Product') continue to work.
            entity.HasDiscriminator<string>("Discriminator");

            // EF Core 9 no longer embeds the discriminator in the JSON id property.
            // Preserve the old "Product|123" format so existing documents remain accessible
            // via FindAsync / point-reads and direct queries on c.id.
            entity.HasRootDiscriminatorInJsonId(true);

            // HasIndex throws InvalidOperationException in EF Core 9 Cosmos provider.
            // Cosmos DB indexing is managed via the container's indexing policy
            // (Azure Portal / Bicep / Terraform), not through EF Core.
            // REMOVED: entity.HasIndex(p => p.Sku);
        });
    }
}
class Product { public int Id { get; set; } public string Sku { get; set; } }

